# Key insight: ALL 4-connected bg pockets (any size!) are recolored in demo 3! Check: pockets sizes 1..10 all fully changed. And in demos 1&2 all pockets were small and fully changed.
# So rule: every bg cell belonging to an enclosed 4-connected pocket -> 4. That's just "fill all enclosed regions". But that failed earlier on test because some pockets touch border... those aren't enclosed. Earlier my first attempt colored only small ones and failed on test; second submit (all enclosed pockets <=3) also wrong. Now try ALL enclosed pockets.
def solve_all(g):
    g=np.array(g); H,W=g.shape
    vals=sorted(set(int(v) for v in g.flat)); bg=vals[0]; mk=vals[-1]
    vis=[[False]*W for _ in range(H)]; q=deque()
    for c in range(W):
        for rr in (0,H-1):
            if g[rr][c]==bg and not vis[rr][c]: vis[rr][c]=True; q.append((rr,c))
    for r in range(H):
        for cc in (0,W-1):
            if g[r][cc]==bg and not vis[r][cc]: vis[r][cc]=True; q.append((r,cc))
    while q:
        y,x=q.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and g[ny][nx]==bg and not vis[ny][nx]:
                vis[ny][nx]=True; q.append((ny,nx))
    out=[[int(v) for v in row] for row in g]
    lab=[[False]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if g[r][c]==bg and not vis[r][c] and not lab[r][c]:
                qq=deque([(r,c)]); lab[r][c]=True
                while qq:
                    y,x=qq.popleft(); out[y][x]=4
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==bg and not lab[ny][nx]:
                            lab[ny][nx]=True; qq.append((ny,nx))
    return out
for p in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    print(p, solve_all(G[p+' input'])==G[p+' output'])
